// iManager-Front 대시보드(DashEditContainer / DashComponent)의 편집·조회 모드를 축약해 재현한 데모.
// 실제 구현: 위젯을 좌표(left/top/width/height)로 관리하고, 헤더 드래그로 이동 / 가장자리 핸들로 리사이즈,
// 10px 격자 스냅, 리사이즈 핸들 더블클릭 시 충돌을 피해 최대로 확장. 편집 모드에서는 위젯마다
// 차트 유형·대상·표시 행 수 등 수신 데이터 설정 폼을 위젯 내부에 렌더한다.

type ChartType =
  | "TRANSACTION"
  | "EXCEPTIONLOG"
  | "LINE"
  | "COLUMN"
  | "DOUGHNUT"
  | "XVIEW"
  | "EXTERNALLINE"
  | "STATISTICS"
  | "TITLE";

type TargetType = "INSTANCE" | "ADAPTER";
type InOut = "IN" | "OUT";
type ResizeDir = "e" | "s" | "se";

interface WidgetCatalogItem {
  itemId: string;
  label: string;
  source?: "5분 Polling";
  chartOptions: ChartType[];
  hasTarget: boolean;
  hasInOut: boolean;
  minWidth: number;
  maxWidth: number;
  minHeight: number;
  maxHeight: number;
  defaultWidth: number;
  defaultHeight: number;
}

interface WidgetInstance {
  id: string;
  itemId: string;
  x: number;
  y: number;
  width: number;
  height: number;
  z: number;
  title: string;
  chartType: ChartType;
  targetType?: TargetType;
  inOut?: InOut;
  rowCnt?: number;
  yAxisMax?: number;
  trans?: string;
  minData?: number;
  restore?: { width: number; height: number } | null;
}

interface DragState {
  id: string;
  mode: "move" | "resize";
  dir?: ResizeDir;
  pointerId: number;
  startX: number;
  startY: number;
  origX: number;
  origY: number;
  origWidth: number;
  origHeight: number;
  minWidth: number;
  maxWidth: number;
  minHeight: number;
  maxHeight: number;
}

interface DropPreview {
  x: number;
  y: number;
  width: number;
  height: number;
  valid: boolean;
  label: string;
}

