const catalogByItemId = new Map(widgetCatalog.map((item) => [item.itemId, item]));

const snap = (value: number): number => Math.round(value / GRID_SIZE) * GRID_SIZE;
const clamp = (value: number, min: number, max: number): number => Math.min(Math.max(value, min), max);

let widgetSeq = 0;
function createId(): string {
  widgetSeq += 1;
  return `dash-widget-${widgetSeq}`;
}

function makeWidget(item: WidgetCatalogItem, x: number, y: number, z: number): WidgetInstance {
  const chartType = item.chartOptions[0];
  return {
    id: createId(),
    itemId: item.itemId,
    x,
    y,
    width: item.defaultWidth,
    height: item.defaultHeight,
    z,
    title: item.label,
    chartType,
    targetType: item.hasTarget ? "INSTANCE" : undefined,
    inOut: item.hasInOut ? "IN" : undefined,
    rowCnt: chartType === "TRANSACTION" || chartType === "EXCEPTIONLOG" ? 10 : undefined,
    yAxisMax: chartType === "XVIEW" ? 5000 : undefined,
    trans: chartType === "XVIEW" ? "1.0" : undefined,
    minData: chartType === "XVIEW" ? 10 : undefined,
    restore: null,
  };
}

const LAYOUT_GAP = 10;
const floorToGap = (n: number): number => Math.floor(n / LAYOUT_GAP) * LAYOUT_GAP;

function layoutWidget(itemId: string, x: number, y: number, width: number, height: number, z: number): WidgetInstance {
  const item = catalogByItemId.get(itemId)!;
  return {
    ...makeWidget(item, x, y, z),
    width: clamp(floorToGap(width), item.minWidth, item.maxWidth),
    height: clamp(floorToGap(height), item.minHeight, item.maxHeight),
  };
}

// 캔버스 크기에 맞춰 초기 위젯을 격자로 깔아, 편집 모드에서도 빈 여백 없이 캔버스를 끝까지 채운다.
function buildInitialLayout(canvasW: number, canvasH: number): WidgetInstance[] {
  const g = LAYOUT_GAP;
  const x0 = g;
  const innerW = floorToGap(canvasW - g * 2);

  // 좁은 화면: 1열 스택
  if (innerW < 500) {
    const stack = ["title", "activeTransaction", "exceptionLog", "cpuUsage", "fileMainUsage", "xView", "externalLineStatus", "statistics"];
    let y = g;
    return stack.map((id, i) => {
      const widget = layoutWidget(id, x0, y, innerW, id === "title" ? 52 : 150, i + 1);
      y += widget.height + g;
      return widget;
    });
  }

  const titleH = 52;
  const bodyTop = g + titleH + g;
  const rowGap = g;
  const rowH = Math.max(120, floorToGap((canvasH - bodyTop - g - rowGap * 2) / 3));
  const r1 = bodyTop;
  const r2 = r1 + rowH + rowGap;
  const r3 = r2 + rowH + rowGap;
  const r3H = Math.max(120, floorToGap(canvasH - r3 - g));

  const wideW = floorToGap(innerW * 0.58);
  const third = floorToGap((innerW - g * 2) / 3);
  const half = floorToGap((innerW - g) / 2);

  return [
    layoutWidget("title", x0, g, innerW, titleH, 1),
    layoutWidget("activeTransaction", x0, r1, wideW, rowH, 2),
    layoutWidget("exceptionLog", x0 + wideW + g, r1, innerW - wideW - g, rowH, 3),
    layoutWidget("cpuUsage", x0, r2, third, rowH, 4),
    layoutWidget("fileMainUsage", x0 + third + g, r2, third, rowH, 5),
    layoutWidget("xView", x0 + (third + g) * 2, r2, innerW - (third + g) * 2, rowH, 6),
    layoutWidget("externalLineStatus", x0, r3, half, r3H, 7),
    layoutWidget("statistics", x0 + half + g, r3, innerW - half - g, r3H, 8),
  ];
}

export function DashboardEditDemo(): ReactElement {
  const [mode, setMode] = useState<"edit" | "view">("edit");
  const [widgets, setWidgets] = useState<WidgetInstance[]>([]);
  const [dropPreview, setDropPreview] = useState<DropPreview | null>(null);
  const canvasRef = useRef<HTMLDivElement | null>(null);
  const workspaceRef = useRef<HTMLDivElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<DragState | null>(null);
  const draggingCatalogRef = useRef<WidgetCatalogItem | null>(null);
  const layoutDirtyRef = useRef(false);
  const lastLayoutRef = useRef({ w: 0, h: 0 });
  const panelDragRef = useRef<{ pointerId: number; startX: number; startY: number; origX: number; origY: number } | null>(null);
  const [panelPos, setPanelPos] = useState<{ x: number; y: number } | null>(null);
  const [panelCollapsed, setPanelCollapsed] = useState(false);

  // 캔버스 크기에 맞춘 초기 격자 배치 — 사용자가 아직 손대지 않은 동안에는 리사이즈에도 다시 채운다.
  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const relayout = (): void => {
      if (layoutDirtyRef.current) return;
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 60) return;
      const w = Math.round(rect.width);
      const h = Math.round(Math.max(rect.height, 520));
      if (Math.abs(w - lastLayoutRef.current.w) < 8 && Math.abs(h - lastLayoutRef.current.h) < 8) return;
      lastLayoutRef.current = { w, h };
      setWidgets(buildInitialLayout(w, h));
    };

    relayout();
    const observer = new ResizeObserver(relayout);
    observer.observe(canvas);
    return () => observer.disconnect();
  }, []);

  const removeWidget = (id: string): void => {
    layoutDirtyRef.current = true;
    setWidgets((prev) => prev.filter((widget) => widget.id !== id));
  };

  const updateWidget = (id: string, patch: Partial<WidgetInstance>): void => {
    setWidgets((prev) => prev.map((widget) => (widget.id === id ? applyPatch(widget, patch) : widget)));
  };

  const bringToFront = (id: string): void => {
    setWidgets((prev) => {
      const max = prev.reduce((m, w) => Math.max(m, w.z), 0);
      return prev.map((widget) => (widget.id === id ? { ...widget, z: max + 1 } : widget));
    });
  };

  const startDrag = (
    evt: ReactPointerEvent<HTMLDivElement>,
    widget: WidgetInstance,
    dragMode: "move" | "resize",
    dir?: ResizeDir,
  ): void => {
    if (mode !== "edit") return;
    const catalogItem = catalogByItemId.get(widget.itemId);
    if (!catalogItem) return;

    evt.stopPropagation();
    (evt.currentTarget as HTMLElement).setPointerCapture(evt.pointerId);
    layoutDirtyRef.current = true;
    bringToFront(widget.id);

    dragRef.current = {
      id: widget.id,
      mode: dragMode,
      dir,
      pointerId: evt.pointerId,
      startX: evt.clientX,
      startY: evt.clientY,
      origX: widget.x,
      origY: widget.y,
      origWidth: widget.width,
      origHeight: widget.height,
      minWidth: catalogItem.minWidth,
      maxWidth: catalogItem.maxWidth,
      minHeight: catalogItem.minHeight,
      maxHeight: catalogItem.maxHeight,
    };
  };

  const onCanvasPointerMove = (evt: ReactPointerEvent<HTMLDivElement>): void => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== evt.pointerId) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const bounds = canvas.getBoundingClientRect();
    const dx = evt.clientX - drag.startX;
    const dy = evt.clientY - drag.startY;

    setWidgets((prev) =>
      prev.map((widget) => {
        if (widget.id !== drag.id) return widget;

        if (drag.mode === "move") {
          const nextX = snap(clamp(drag.origX + dx, 0, Math.max(0, bounds.width - widget.width)));
          const nextY = snap(clamp(drag.origY + dy, 0, Math.max(0, bounds.height - widget.height)));
          return { ...widget, x: nextX, y: nextY };
        }

        let width = widget.width;
        let height = widget.height;

        if (drag.dir === "e" || drag.dir === "se") {
          const maxAvailable = Math.max(drag.minWidth, bounds.width - widget.x);
          width = snap(clamp(drag.origWidth + dx, drag.minWidth, Math.min(drag.maxWidth, maxAvailable)));
        }
        if (drag.dir === "s" || drag.dir === "se") {
          const maxAvailable = Math.max(drag.minHeight, bounds.height - widget.y);
          height = snap(clamp(drag.origHeight + dy, drag.minHeight, Math.min(drag.maxHeight, maxAvailable)));
        }
        return { ...widget, width, height, restore: null };
      }),
    );
  };

  const endDrag = (): void => {
    dragRef.current = null;
  };

  // 위젯 목록 패널을 캔버스 위에서 자유롭게 옮길 수 있게 (iManager의 draggable 위젯 모달과 동일한 취지)
  const startPanelDrag = (evt: ReactPointerEvent<HTMLDivElement>): void => {
    const panel = panelRef.current;
    const workspace = workspaceRef.current;
    if (!panel || !workspace) return;

    const panelRect = panel.getBoundingClientRect();
    const wsRect = workspace.getBoundingClientRect();
    const origX = panelRect.left - wsRect.left;
    const origY = panelRect.top - wsRect.top;

    (evt.currentTarget as HTMLElement).setPointerCapture(evt.pointerId);
    panelDragRef.current = { pointerId: evt.pointerId, startX: evt.clientX, startY: evt.clientY, origX, origY };
    setPanelPos({ x: origX, y: origY });
  };

  const onPanelPointerMove = (evt: ReactPointerEvent<HTMLDivElement>): void => {
    const drag = panelDragRef.current;
    if (!drag || drag.pointerId !== evt.pointerId) return;

    const panel = panelRef.current;
    const workspace = workspaceRef.current;
    if (!panel || !workspace) return;

    const wsRect = workspace.getBoundingClientRect();
    const nextX = clamp(drag.origX + (evt.clientX - drag.startX), 0, Math.max(0, wsRect.width - panel.offsetWidth));
    const nextY = clamp(drag.origY + (evt.clientY - drag.startY), 0, Math.max(0, wsRect.height - panel.offsetHeight));
    setPanelPos({ x: nextX, y: nextY });
  };

  const endPanelDrag = (): void => {
    panelDragRef.current = null;
  };

  // 리사이즈 핸들 더블클릭 — 실제 구현의 "충돌을 피해 최대로 확장 / 다시 최소로" 동작을 축약 재현
  const toggleExpand = (widget: WidgetInstance): void => {
    const canvas = canvasRef.current;
    const catalogItem = catalogByItemId.get(widget.itemId);
    if (!canvas || !catalogItem) return;
    layoutDirtyRef.current = true;
    const bounds = canvas.getBoundingClientRect();

    if (widget.restore) {
      updateWidget(widget.id, { width: widget.restore.width, height: widget.restore.height, restore: null });
      return;
    }

    const others = widgets.filter((w) => w.id !== widget.id);
    const overlapsY = (w: WidgetInstance): boolean =>
      w.y < widget.y + widget.height && w.y + w.height > widget.y;
    const overlapsX = (w: WidgetInstance): boolean =>
      w.x < widget.x + widget.width && w.x + w.width > widget.x;

    const rightWall = Math.min(
      bounds.width,
      ...others.filter((w) => w.x >= widget.x + widget.width && overlapsY(w)).map((w) => w.x - GRID_SIZE),
    );
    const bottomWall = Math.min(
      bounds.height,
      ...others.filter((w) => w.y >= widget.y + widget.height && overlapsX(w)).map((w) => w.y - GRID_SIZE),
    );

    const width = snap(clamp(rightWall - widget.x, catalogItem.minWidth, catalogItem.maxWidth));
    const height = snap(clamp(bottomWall - widget.y, catalogItem.minHeight, catalogItem.maxHeight));

    updateWidget(widget.id, { width, height, restore: { width: widget.width, height: widget.height } });
  };

  // 위젯 목록에서 캔버스로 드래그 앤 드롭
  useEffect(() => {
    const onPointerMove = (evt: PointerEvent): void => {
      const catalogItem = draggingCatalogRef.current;
      const canvas = canvasRef.current;
      if (!catalogItem || !canvas) return;

      const bounds = canvas.getBoundingClientRect();
      const width = catalogItem.defaultWidth;
      const height = catalogItem.defaultHeight;
      const x = snap(evt.clientX - bounds.left - width / 2);
      const y = snap(evt.clientY - bounds.top - height / 2);
      const valid = x >= 0 && y >= 0 && x + width <= bounds.width && y + height <= bounds.height;

      setDropPreview({ x, y, width, height, valid, label: catalogItem.label });
    };

    const onPointerUp = (): void => {
      const catalogItem = draggingCatalogRef.current;
      draggingCatalogRef.current = null;

      setDropPreview((prev) => {
        if (catalogItem && prev && prev.valid) {
          layoutDirtyRef.current = true;
          setWidgets((list) => [...list, makeWidget(catalogItem, prev.x, prev.y, list.reduce((m, w) => Math.max(m, w.z), 0) + 1)]);
        }
        return null;
      });
    };

    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    return () => {
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
    };
  }, []);

  return (
    <article className="dashboard-edit-demo interactive" aria-label="대시보드 위젯 편집 데모">
      <header>
        <div>
          <p className="eyebrow">{mode === "view" ? "VIEW MODE" : "EDIT MODE"}</p>
          <h3>
            {mode === "view"
              ? "설정한 레이아웃과 차트로 렌더링된 조회 화면"
              : "위젯마다 차트 유형·대상·표시 행 수를 설정합니다"}
          </h3>
        </div>
        <button
          type="button"
          className="dashboard-edit-preview-toggle"
          onClick={() => setMode((prev) => (prev === "edit" ? "view" : "edit"))}
        >
          {mode === "view" ? <Pencil size={15} aria-hidden="true" /> : <Eye size={15} aria-hidden="true" />}
          {mode === "view" ? "편집으로" : "조회 미리보기"}
        </button>
      </header>

      <div className={`dashboard-edit-workspace ${mode}`} ref={workspaceRef}>
        <div
          ref={canvasRef}
          className={`dashboard-edit-canvas interactive ${mode}`}
          style={{ minHeight: Math.max(520, widgets.reduce((m, w) => Math.max(m, w.y + w.height), 0) + LAYOUT_GAP) }}
          onPointerMove={onCanvasPointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
        >
          {widgets.length === 0 && mode === "edit" && (
            <p className="dashboard-edit-empty">
              <Plus size={18} aria-hidden="true" />
              위젯 목록에서 항목을 끌어와 배치
            </p>
          )}

          {widgets.map((widget) => {
            const catalogItem = catalogByItemId.get(widget.itemId);
            if (!catalogItem) return null;

            return (
              <div
                key={widget.id}
                className={`dash-widget ${widget.itemId} ${mode}`}
                style={{ left: widget.x, top: widget.y, width: widget.width, height: widget.height, zIndex: widget.z }}
              >
                <div
                  className="dash-widget-header"
                  onPointerDown={(evt) => startDrag(evt, widget, "move")}
                >
                  {mode === "edit" && <GripHorizontal className="dash-widget-grip" size={12} aria-hidden="true" />}
                  <span className="dash-widget-title" title={widget.title}>
                    {widget.itemId === "title" ? "제목" : widget.title}
                  </span>
                  {mode === "edit" && (
                    <button
                      type="button"
                      className="dash-widget-remove"
                      aria-label={`${widget.title} 위젯 삭제`}
                      onPointerDown={(evt) => evt.stopPropagation()}
                      onClick={() => removeWidget(widget.id)}
                    >
                      <X size={11} aria-hidden="true" />
                    </button>
                  )}
                </div>

                <div className="dash-widget-body">
                  {mode === "edit" ? (
                    <WidgetEditForm widget={widget} catalogItem={catalogItem} onChange={(patch) => updateWidget(widget.id, patch)} />
                  ) : (
                    <WidgetChart widget={widget} />
                  )}
                </div>

                {mode === "edit" && (
                  <>
                    <div
                      className="dash-resize-handle e"
                      onPointerDown={(evt) => startDrag(evt, widget, "resize", "e")}
                      onDoubleClick={() => toggleExpand(widget)}
                      aria-hidden="true"
                    />
                    <div
                      className="dash-resize-handle s"
                      onPointerDown={(evt) => startDrag(evt, widget, "resize", "s")}
                      onDoubleClick={() => toggleExpand(widget)}
                      aria-hidden="true"
                    />
                    <div
                      className="dash-resize-handle se"
                      onPointerDown={(evt) => startDrag(evt, widget, "resize", "se")}
                      onDoubleClick={() => toggleExpand(widget)}
                      title={widget.restore ? "더블클릭: 원래 크기로" : "더블클릭: 최대 크기로"}
                      aria-hidden="true"
                    />
                  </>
                )}
              </div>
            );
          })}

          {dropPreview && (
            <div
              className={`dashboard-edit-drop-preview ${dropPreview.valid ? "valid" : "invalid"}`}
              style={{ left: dropPreview.x, top: dropPreview.y, width: dropPreview.width, height: dropPreview.height }}
            >
              {dropPreview.valid ? `${dropPreview.label} 놓기` : "캔버스 안에 놓아주세요"}
            </div>
          )}
        </div>

        {mode === "edit" && (
          <div
            ref={panelRef}
            className={`dashboard-edit-add-panel${panelCollapsed ? " collapsed" : ""}`}
            aria-label="위젯 목록"
            style={panelPos ? { left: panelPos.x, top: panelPos.y, right: "auto" } : undefined}
            onPointerMove={onPanelPointerMove}
            onPointerUp={endPanelDrag}
            onPointerCancel={endPanelDrag}
          >
            <div className="dashboard-edit-add-handle" onPointerDown={startPanelDrag}>
              <GripHorizontal size={13} aria-hidden="true" />
              <span>위젯</span>
              <button
                type="button"
                className="dashboard-edit-add-collapse"
                aria-label={panelCollapsed ? "위젯 목록 펼치기" : "위젯 목록 접기"}
                onPointerDown={(evt) => evt.stopPropagation()}
                onClick={() => setPanelCollapsed((prev) => !prev)}
              >
                {panelCollapsed ? <ChevronDown size={13} aria-hidden="true" /> : <ChevronUp size={13} aria-hidden="true" />}
              </button>
            </div>
            <div className="dashboard-edit-add-list">
              {widgetCatalog.map((item) => (
                <div
                  key={item.itemId}
                  className="dashboard-perf-item"
                  onPointerDown={() => {
                    draggingCatalogRef.current = item;
                  }}
                >
                  <GripVertical className="dashboard-perf-grip" size={13} aria-hidden="true" />
                  <span className="dashboard-perf-label">
                    <strong>{item.label}</strong>
                    {item.source && <small>{item.source}</small>}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </article>
  );
}

function applyPatch(widget: WidgetInstance, patch: Partial<WidgetInstance>): WidgetInstance {
  const next = { ...widget, ...patch };
  // 차트 유형이 바뀌면 유형별 옵션 필드를 초기화 (DashComponent의 chartType 변경 로직과 동일한 취지)
  if (patch.chartType && patch.chartType !== widget.chartType) {
    next.rowCnt = patch.chartType === "TRANSACTION" || patch.chartType === "EXCEPTIONLOG" ? 10 : undefined;
    next.yAxisMax = patch.chartType === "XVIEW" ? 5000 : undefined;
    next.trans = patch.chartType === "XVIEW" ? "1.0" : undefined;
    next.minData = patch.chartType === "XVIEW" ? 10 : undefined;
  }
  return next;
}

function WidgetEditForm({
  widget,
  catalogItem,
  onChange,
}: {
  widget: WidgetInstance;
  catalogItem: WidgetCatalogItem;
  onChange: (patch: Partial<WidgetInstance>) => void;
}): ReactElement {
  const numberField = (key: "rowCnt" | "yAxisMax" | "minData", label: string): ReactElement => (
    <label className="dash-field">
      <span>{label}</span>
      <input
        type="number"
        value={widget[key] ?? ""}
        onChange={(evt: ChangeEvent<HTMLInputElement>) =>
          onChange({ [key]: evt.target.value === "" ? undefined : Number(evt.target.value) } as Partial<WidgetInstance>)
        }
      />
    </label>
  );

  return (
    <div className="dash-widget-form" onPointerDown={(evt) => evt.stopPropagation()}>
      <label className="dash-field">
        <span>이름</span>
        <input
          type="text"
          value={widget.title}
          onChange={(evt: ChangeEvent<HTMLInputElement>) => onChange({ title: evt.target.value })}
        />
      </label>

      {widget.itemId !== "title" && (
        <label className="dash-field">
          <span>차트 유형</span>
          <select
            value={widget.chartType}
            disabled={catalogItem.chartOptions.length < 2}
            onChange={(evt) => onChange({ chartType: evt.target.value as ChartType })}
          >
            {catalogItem.chartOptions.map((option) => (
              <option key={option} value={option}>
                {CHART_LABEL[option]}
              </option>
            ))}
          </select>
        </label>
      )}

      {catalogItem.hasTarget && widget.chartType !== "STATISTICS" && (
        <label className="dash-field">
          <span>대상</span>
          <select
            value={widget.targetType}
            onChange={(evt) => onChange({ targetType: evt.target.value as TargetType })}
          >
            <option value="INSTANCE">INSTANCE</option>
            <option value="ADAPTER">ADAPTER</option>
          </select>
        </label>
      )}

      {catalogItem.hasInOut && (
        <label className="dash-field">
          <span>IN / OUT</span>
          <select value={widget.inOut} onChange={(evt) => onChange({ inOut: evt.target.value as InOut })}>
            <option value="IN">IN</option>
            <option value="OUT">OUT</option>
          </select>
        </label>
      )}

      {(widget.chartType === "TRANSACTION" || widget.chartType === "EXCEPTIONLOG") &&
        numberField("rowCnt", "표시 행 수")}

      {widget.chartType === "XVIEW" && (
        <>
          {numberField("yAxisMax", "Y축 최대값")}
          <label className="dash-field">
            <span>데이터 변환</span>
            <input
              type="text"
              value={widget.trans ?? ""}
              onChange={(evt: ChangeEvent<HTMLInputElement>) => onChange({ trans: evt.target.value })}
            />
          </label>
          {numberField("minData", "최소 데이터")}
        </>
      )}

      {catalogItem.source && <span className="dash-widget-source">{catalogItem.source}</span>}
    </div>
  );
}

function WidgetChart({ widget }: { widget: WidgetInstance }): ReactElement {
  switch (widget.chartType) {
    case "TITLE":
      return <div className="dash-chart-title">{widget.title}</div>;
    case "TRANSACTION":
      return <TransactionTable rowCnt={widget.rowCnt ?? 10} />;
    case "EXCEPTIONLOG":
      return <ExceptionTable rowCnt={widget.rowCnt ?? 10} />;
    case "LINE":
      return <LineChart />;
    case "COLUMN":
      return <ColumnChart />;
    case "DOUGHNUT":
      return <DoughnutChart />;
    case "XVIEW":
      return <XViewChart />;
    case "EXTERNALLINE":
      return <ExternalLineGrid />;
    case "STATISTICS":
      return <StatisticsCards />;
    default:
      return <div className="dash-chart-empty">{widget.chartType}</div>;
  }
}

